import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"高频面试题：Agent 框架方向","description":"","frontmatter":{},"headers":[],"relativePath":"interview/qa.md","filePath":"interview/qa.md","lastUpdated":null}'),n={name:"interview/qa.md"};function s(l,e,c,i,d,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="高频面试题-agent-框架方向" tabindex="-1">高频面试题：Agent 框架方向 <a class="header-anchor" href="#高频面试题-agent-框架方向" aria-label="Permalink to &quot;高频面试题：Agent 框架方向&quot;">​</a></h1><blockquote><p>按四类组织：概念题（考理解）、源码题（考深度）、系统设计题（考迁移）、场景题（考实战）。每题给答案要点，括号里标注证据来源章节。</p></blockquote><h2 id="一、概念题" tabindex="-1">一、概念题 <a class="header-anchor" href="#一、概念题" aria-label="Permalink to &quot;一、概念题&quot;">​</a></h2><h3 id="q1-dsh-说-一切皆插件-agent-loop-本身也是插件-怎么理解" tabindex="-1">Q1. DSH 说&quot;一切皆插件&quot;，Agent Loop 本身也是插件，怎么理解？ <a class="header-anchor" href="#q1-dsh-说-一切皆插件-agent-loop-本身也是插件-怎么理解" aria-label="Permalink to &quot;Q1. DSH 说&quot;一切皆插件&quot;，Agent Loop 本身也是插件，怎么理解？&quot;">​</a></h3><p><strong>要点</strong>：loop 是挂在 <code>ctx.agentLoop</code> 的默认实现（<code>ReactLoopAgent</code>）；扩展包依赖 <code>dsh-agent</code> 的事件与服务而非该包；组合包 <code>dsh-base</code> 只是第一层 patch，其上任何条目都可被覆盖。<strong>没有需要打补丁的特权内核</strong>。</p><h3 id="q2-turn-和-step-的区别-一个-turn-里没有-step-可能吗" tabindex="-1">Q2. turn 和 step 的区别？一个 turn 里没有 step 可能吗？ <a class="header-anchor" href="#q2-turn-和-step-的区别-一个-turn-里没有-step-可能吗" aria-label="Permalink to &quot;Q2. turn 和 step 的区别？一个 turn 里没有 step 可能吗？&quot;">​</a></h3><p><strong>要点</strong>：turn 是排空已接纳输入的过程，step 是一次模型请求+工具执行。可能——<code>agent/pre-step</code> 拒绝或首次 enter 改写为空时，仍关闭一个无步骤的持久轮次，日志记录这次尝试。</p><h3 id="q3-waterfall-事件的-next-语义" tabindex="-1">Q3. waterfall 事件的 <code>next()</code> 语义？ <a class="header-anchor" href="#q3-waterfall-事件的-next-语义" aria-label="Permalink to &quot;Q3. waterfall 事件的 `next()` 语义？&quot;">​</a></h3><p><strong>要点</strong>：环绕中间件。调 <code>next()</code> 委托下游、返回值可被本层包装；不调直接 return = 短路（单决策事件的设计意图）。纯观察者必须委托。</p><h3 id="q4-会话事件、agent-事件、能力事件三个域怎么选" tabindex="-1">Q4. 会话事件、Agent 事件、能力事件三个域怎么选？ <a class="header-anchor" href="#q4-会话事件、agent-事件、能力事件三个域怎么选" aria-label="Permalink to &quot;Q4. 会话事件、Agent 事件、能力事件三个域怎么选？&quot;">​</a></h3><p><strong>要点</strong>：事实必须重载后仍存在 → 会话事件（追加日志+广播）；观察/拦截进行中工作 → <code>agent/*</code>；给 seam 挂策略避免 import 循环 → <code>fs/*</code>、<code>tools/*</code>。架构决策第一问。</p><h3 id="q5-模型可见即已记录-是什么-为什么重要" tabindex="-1">Q5. &quot;模型可见即已记录&quot;是什么？为什么重要？ <a class="header-anchor" href="#q5-模型可见即已记录-是什么-为什么重要" aria-label="Permalink to &quot;Q5. &quot;模型可见即已记录&quot;是什么？为什么重要？&quot;">​</a></h3><p><strong>要点</strong>：到达模型请求的一切必须能从日志重建，运行时不变量断言。否则回放、审计、fork、恢复全部失效。新增模型可见输入 = 必须新增会话事件。</p><h3 id="q6-能力-seam-的三个角色-为什么-单一角色不是-seam" tabindex="-1">Q6. 能力 seam 的三个角色？为什么&quot;单一角色不是 seam&quot;？ <a class="header-anchor" href="#q6-能力-seam-的三个角色-为什么-单一角色不是-seam" aria-label="Permalink to &quot;Q6. 能力 seam 的三个角色？为什么&quot;单一角色不是 seam&quot;？&quot;">​</a></h3><p><strong>要点</strong>：Service Definition（抽象类+词汇，非 TS interface）/ Provider / Consumer。只有一半会导致&quot;一个 Consumer 说了算的服务契约&quot;或无人可替换的假抽象。</p><h3 id="q7-sandbox-的三种模式管什么-为什么-sandboxpolicy-不含-danger-full-access" tabindex="-1">Q7. sandbox 的三种模式管什么？为什么 SandboxPolicy 不含 danger-full-access？ <a class="header-anchor" href="#q7-sandbox-的三种模式管什么-为什么-sandboxpolicy-不含-danger-full-access" aria-label="Permalink to &quot;Q7. sandbox 的三种模式管什么？为什么 SandboxPolicy 不含 danger-full-access？&quot;">​</a></h3><p><strong>要点</strong>：只管文件效果：read-only / workspace-write / danger-full-access。danger-full-access 语义是&quot;消费方根本不调 confine&quot;——把它当策略值会造成&quot;沙箱包装空操作&quot;的假象。</p><h3 id="q8-goal-的-phase-与-activation-为什么分离" tabindex="-1">Q8. goal 的 phase 与 activation 为什么分离？ <a class="header-anchor" href="#q8-goal-的-phase-与-activation-为什么分离" aria-label="Permalink to &quot;Q8. goal 的 phase 与 activation 为什么分离？&quot;">​</a></h3><p><strong>要点</strong>：phase（active/paused/blocked/complete）是持久事实；activation（armed/disarmed）是进程本地意愿。session-start 自动 disarm——旧目标不会在新会话里偷偷续跑，必须显式 resume。</p><h2 id="二、源码题" tabindex="-1">二、源码题 <a class="header-anchor" href="#二、源码题" aria-label="Permalink to &quot;二、源码题&quot;">​</a></h2><h3 id="q9-工具执行流水线的完整顺序" tabindex="-1">Q9. 工具执行流水线的完整顺序？ <a class="header-anchor" href="#q9-工具执行流水线的完整顺序" aria-label="Permalink to &quot;Q9. 工具执行流水线的完整顺序？&quot;">​</a></h3><p><strong>要点</strong>：materialize（快照+冻结+collapse 判定）→ <code>tools/pre-execute</code>（allow/deny/ask）→ guard 链（只减权限）→ approval（allowed-once）→ <code>tools/execute</code>（around：timeout 替换 signal）→ 函数体 → <code>tools/post-execute</code>（accept/block/替换）→ <code>finalizeContent</code>（快照回调，只改 content）→ materialize+freeze → <code>tools/result</code>（同步观察，不可改写）。</p><h3 id="q10-工具并发调度-exclusive-barrier-和-parallel-rolling-pool-是什么-为什么-提交前重分类" tabindex="-1">Q10. 工具并发调度：exclusive barrier 和 parallel rolling pool 是什么？为什么&quot;提交前重分类&quot;？ <a class="header-anchor" href="#q10-工具并发调度-exclusive-barrier-和-parallel-rolling-pool-是什么-为什么-提交前重分类" aria-label="Permalink to &quot;Q10. 工具并发调度：exclusive barrier 和 parallel rolling pool 是什么？为什么&quot;提交前重分类&quot;？&quot;">​</a></h3><p><strong>要点</strong>：executionMode 分类（只有 <code>isConcurrencySafe(args)===true</code> 才并行）；exclusive 单组成屏障；parallel 进容量 <code>maxParallelToolCalls</code> 的滚动池。reclassify 让注册表/守卫在提交间隙的变更即时生效。提交按模型顺序（<code>commitReady</code> 只推进连续前缀）。</p><h3 id="q11-取消时为什么给未启动的工具合成-aborted-before-dispatch-结果" tabindex="-1">Q11. 取消时为什么给未启动的工具合成&quot;aborted before dispatch&quot;结果？ <a class="header-anchor" href="#q11-取消时为什么给未启动的工具合成-aborted-before-dispatch-结果" aria-label="Permalink to &quot;Q11. 取消时为什么给未启动的工具合成&quot;aborted before dispatch&quot;结果？&quot;">​</a></h3><p><strong>要点</strong>：日志不变量：每个 <code>tool/call</code> 必须配对 <code>tool/result</code>。合成结果让取消后的日志依然完整合法——回放器、UI、deriveMessages 都依赖配对。</p><h3 id="q12-compaction-的锁如何实现-崩溃后如何恢复" tabindex="-1">Q12. compaction 的锁如何实现？崩溃后如何恢复？ <a class="header-anchor" href="#q12-compaction-的锁如何实现-崩溃后如何恢复" aria-label="Permalink to &quot;Q12. compaction 的锁如何实现？崩溃后如何恢复？&quot;">​</a></h3><p><strong>要点</strong>：<code>compaction/start</code>…<code>compaction/end</code> 日志配对即锁；&quot;有 start 无 end&quot; = 崩溃遗留锁 → busy；<code>session/end-seed</code> 之前的遗留 start 视为旧生命周期残留。</p><h3 id="q13-溢出恢复为什么看-surface-replacegeneration-是否前进" tabindex="-1">Q13. 溢出恢复为什么看 <code>surface.replaceGeneration</code> 是否前进？ <a class="header-anchor" href="#q13-溢出恢复为什么看-surface-replacegeneration-是否前进" aria-label="Permalink to &quot;Q13. 溢出恢复为什么看 `surface.replaceGeneration` 是否前进？&quot;">​</a></h3><p><strong>要点</strong>：replaceGeneration = 已提交位置替换的持久计数。剪枝或摘要的 replace 落地（代数前进）→ 重试从新表层出发；否则盲目重放同样溢出的旧请求。<strong>用日志状态而非内存状态证明进展</strong>。</p><h3 id="q14-摘要调用如何省-kv-cache" tabindex="-1">Q14. 摘要调用如何省 KV cache？ <a class="header-anchor" href="#q14-摘要调用如何省-kv-cache" aria-label="Permalink to &quot;Q14. 摘要调用如何省 KV cache？&quot;">​</a></h3><p><strong>要点</strong>：请求 = 会话自己的 system + tools + 被遮蔽消息 + 压缩指令作为最后一条 user 消息——上次真实请求的<strong>前缀</strong>，提供方前缀缓存不失效。</p><h3 id="q15-workflow-的-fatal-错误怎么区分-为什么脚本伪造不了" tabindex="-1">Q15. workflow 的 fatal 错误怎么区分？为什么脚本伪造不了？ <a class="header-anchor" href="#q15-workflow-的-fatal-错误怎么区分-为什么脚本伪造不了" aria-label="Permalink to &quot;Q15. workflow 的 fatal 错误怎么区分？为什么脚本伪造不了？&quot;">​</a></h3><p><strong>要点</strong>：<code>WorkflowError.fatal</code> 布尔；<code>isFatalWorkflowError</code> 用<strong>宿主 realm 的 instanceof</strong> 判定——脚本 realm 的类无法通过宿主的 instanceof。fatal 杀脚本，普通错误逐项 null。</p><h3 id="q16-凭据如何防泄漏-四层分层是什么" tabindex="-1">Q16. 凭据如何防泄漏？四层分层是什么？ <a class="header-anchor" href="#q16-凭据如何防泄漏-四层分层是什么" aria-label="Permalink to &quot;Q16. 凭据如何防泄漏？四层分层是什么？&quot;">​</a></h3><p><strong>要点</strong>：配置只存环境变量名；每次操作解析；key 只进传输层 authorization 头；错误只点名 ref。分层：进程环境 &gt; <code>$DSH_HOME/.credentials.yaml</code>(0600) &gt; 项目 <code>.env</code> &gt; 用户 <code>.env</code>。</p><h3 id="q17-前端为什么-带状态帧全量快照-session-event-增量-混合" tabindex="-1">Q17. 前端为什么&quot;带状态帧全量快照 + session/event 增量&quot;混合？ <a class="header-anchor" href="#q17-前端为什么-带状态帧全量快照-session-event-增量-混合" aria-label="Permalink to &quot;Q17. 前端为什么&quot;带状态帧全量快照 + session/event 增量&quot;混合？&quot;">​</a></h3><p><strong>要点</strong>：queue/jobs/projection 是 last-wins 派生状态，全量重发自愈；日志帧是追加事实只能增量。<code>session/subscribed</code> 携带基线水位支持重连。</p><h2 id="三、系统设计题" tabindex="-1">三、系统设计题 <a class="header-anchor" href="#三、系统设计题" aria-label="Permalink to &quot;三、系统设计题&quot;">​</a></h2><h3 id="q18-设计一个-agent-的会话持久化-要点" tabindex="-1">Q18. 设计一个 agent 的会话持久化，要点？ <a class="header-anchor" href="#q18-设计一个-agent-的会话持久化-要点" aria-label="Permalink to &quot;Q18. 设计一个 agent 的会话持久化，要点？&quot;">​</a></h3><p><strong>要点</strong>（DSH 答案）：append-only 事件日志唯一真源；派生视图是纯函数折叠；修改=追加+遮蔽（surfaceOp: replace）；请求信封（system+tools+config）写 <code>request/header</code>；运行时不变量重算&quot;请求=日志纯函数&quot;；未知事件 fail-loud 拒绝重建；备份后端换实现不换事件词汇。</p><h3 id="q19-设计-agent-的工具权限系统-要点" tabindex="-1">Q19. 设计 agent 的工具权限系统，要点？ <a class="header-anchor" href="#q19-设计-agent-的工具权限系统-要点" aria-label="Permalink to &quot;Q19. 设计 agent 的工具权限系统，要点？&quot;">​</a></h3><p><strong>要点</strong>：双轨策略（可扩展瀑布 allow/deny/ask + 单调守卫只减权限）；fail-closed（未知工具=exclusive、无审批通道=拒绝、沙箱缺失=不裸跑）；升级严格变宽+allowed-once 单次授权；策略对模型可见（模型知道限制才能正确重试）。</p><h3 id="q20-设计上下文压缩-要点" tabindex="-1">Q20. 设计上下文压缩，要点？ <a class="header-anchor" href="#q20-设计上下文压缩-要点" aria-label="Permalink to &quot;Q20. 设计上下文压缩，要点？&quot;">​</a></h3><p><strong>要点</strong>：成本阶梯（计量→剪枝→摘要→spill）；触发点选 pre-step（策略不打断流程）与 request-error（溢出恢复）；切点工具配对平衡；摘要必须更小（校验）；剪枝先行的确定性收益；恢复进展用持久代数证明。</p><h3 id="q21-设计多代理编排-要点" tabindex="-1">Q21. 设计多代理编排，要点？ <a class="header-anchor" href="#q21-设计多代理编排-要点" aria-label="Permalink to &quot;Q21. 设计多代理编排，要点？&quot;">​</a></h3><p><strong>要点</strong>：委托原语（one-shot）+ 可继续对话（Activation 驻留纪元，inbox 唯一队列）；冷恢复折叠描述符不经 Provider；所有权图 child-first 释放；脚本编排跑受限 vm（containment 非 security）；失败类型化（fatal vs null vs stopReason）；子代理不能问用户（无人可答会永久阻塞）。</p><h3 id="q22-设计一个浏览器端-agent-控制台-要点" tabindex="-1">Q22. 设计一个浏览器端 agent 控制台，要点？ <a class="header-anchor" href="#q22-设计一个浏览器端-agent-控制台-要点" aria-label="Permalink to &quot;Q22. 设计一个浏览器端 agent 控制台，要点？&quot;">​</a></h3><p><strong>要点</strong>：非对称传输（HTTP 上行+WS 下行）；帧协议&quot;快照帧全量+日志帧增量&quot;；数据对象层零 React（uSES 订阅）；增量折叠引擎（node definition 状态机）；slot 系统组合 UI；信任围栏（DNS rebinding）；启动图注入+rev 哈希缓存失效。</p><h2 id="四、场景题" tabindex="-1">四、场景题 <a class="header-anchor" href="#四、场景题" aria-label="Permalink to &quot;四、场景题&quot;">​</a></h2><h3 id="q23-模型在只读沙箱写文件被拒-如何设计完整重试闭环" tabindex="-1">Q23. 模型在只读沙箱写文件被拒，如何设计完整重试闭环？ <a class="header-anchor" href="#q23-模型在只读沙箱写文件被拒-如何设计完整重试闭环" aria-label="Permalink to &quot;Q23. 模型在只读沙箱写文件被拒，如何设计完整重试闭环？&quot;">​</a></h3><p><strong>要点</strong>：拒绝标记带模式名 → 模型同命令+sandbox_permissions+justification 重试 → 工具层执行前 approveEscalation（严格变宽检查→审批→allowed-once 授权本次调用）→ granted mode 只盖本次 policy 不写入会话。</p><h3 id="q24-给所有工具加审计日志-动哪里" tabindex="-1">Q24. 给所有工具加审计日志，动哪里？ <a class="header-anchor" href="#q24-给所有工具加审计日志-动哪里" aria-label="Permalink to &quot;Q24. 给所有工具加审计日志，动哪里？&quot;">​</a></h3><p><strong>要点</strong>：监听 <code>tools/pre-execute</code> / <code>tools/result</code>（scope 过滤），<strong>不动 agent-loop</strong>。这就是&quot;插件，不改循环&quot;。</p><h3 id="q25-如何给子代理只开放部分工具" tabindex="-1">Q25. 如何给子代理只开放部分工具？ <a class="header-anchor" href="#q25-如何给子代理只开放部分工具" aria-label="Permalink to &quot;Q25. 如何给子代理只开放部分工具？&quot;">​</a></h3><p><strong>要点</strong>：父 scope <code>tools.restrict({allow: [...]})</code>——只滤继承面；子自己的注册不受限（回报工具还在）。toolFilter 是可见性（prompt 消失+拒绝执行一体）。</p><h3 id="q26-发现-agent-陷入重复工具调用循环-怎么破" tabindex="-1">Q26. 发现 agent 陷入重复工具调用循环，怎么破？ <a class="header-anchor" href="#q26-发现-agent-陷入重复工具调用循环-怎么破" aria-label="Permalink to &quot;Q26. 发现 agent 陷入重复工具调用循环，怎么破？&quot;">​</a></h3><p><strong>要点</strong>：观察而非否决——<code>repeat-tool-reminder</code> 在 post-execute 计数（canonical 参数串），命中阈值注入提醒（additionalContexts），用户消息重置。保持 loop 自由度，用模型可见提示打破循环。</p><h3 id="q27-一个长任务需要后台执行并随时读取进度-怎么设计" tabindex="-1">Q27. 一个长任务需要后台执行并随时读取进度，怎么设计？ <a class="header-anchor" href="#q27-一个长任务需要后台执行并随时读取进度-怎么设计" aria-label="Permalink to &quot;Q27. 一个长任务需要后台执行并随时读取进度，怎么设计？&quot;">​</a></h3><p><strong>要点</strong>：jobs seam——生产方注册（controller 门禁）；<code>readOutput()</code> 增量语义；first-wins 结算 + <code>reported</code> 记账位防重复通知；完成通知最后投递（reporter 可能同步开轮次）；teardown 取消一律标 reported。</p><h3 id="q28-如果让你给-dsh-加一个-weather-工具-完整步骤" tabindex="-1">Q28. 如果让你给 DSH 加一个 <code>weather</code> 工具，完整步骤？ <a class="header-anchor" href="#q28-如果让你给-dsh-加一个-weather-工具-完整步骤" aria-label="Permalink to &quot;Q28. 如果让你给 DSH 加一个 `weather` 工具，完整步骤？&quot;">​</a></h3><p><strong>要点</strong>（详见<a href="/practice/extend">实战篇</a>）：新包 <code>dsh-tool-weather</code> → <code>defineTool</code>（schema+output+execute）→ 插件 apply 里 <code>ctx.tools.register</code> → system prompt 自动注入 schema → REAL-composition 测试 + keyless snapshot → README Model Experience 格式。</p><hr><h2 id="冲刺建议" tabindex="-1">冲刺建议 <a class="header-anchor" href="#冲刺建议" aria-label="Permalink to &quot;冲刺建议&quot;">​</a></h2><ol><li><strong>每章选 2 个&quot;源码题&quot;讲出代码级细节</strong>（事件名、类型、行号级理解），这比背概念杀伤力大得多</li><li><strong>每个模式准备一句&quot;话术&quot;</strong>（见<a href="/interview/patterns">设计模式手册</a>），面试时自然抛出</li><li><strong>准备 3 个&quot;权衡故事&quot;</strong>：为什么剪枝先于摘要、为什么 vm 是 containment 不是 security、为什么 goal 的 activation 不持久化——这类&quot;为什么&quot;是最能体现深度的回答</li><li>面试前把<a href="/guide/concepts">核心概念</a>的术语表过一遍，准确使用 seam/scope/turn/step/surface 这些词本身就是信号</li></ol>',65)])])}const p=a(n,[["render",s]]);export{q as __pageData,p as default};
